fn run() -> Result<(), String> {
    let mut args = std::env::args().skip(1).peekable();
    if args.peek().is_some_and(|a| a == "--help" || a == "-h") {
        println!("{HELP}");
        return Ok(());
    }
    let command = if args.peek().is_some_and(|a| !a.starts_with('-')) {
        args.next().unwrap()
    } else {
        "check".into()
    };
    let allowed: &[&str] = match command.as_str() {
        "check" | "requirements" => &["--root", "--requirement"],
        "input" => &["--root", "--path", "--line-start", "--line-end"],
        _ => return Err(format!("unknown command {command}\n{HELP}")),
    };
    let mut options = BTreeMap::new();
    while let Some(key) = args.next() {
        if !allowed.contains(&key.as_str()) {
            return Err(format!("unknown option {key}\n{HELP}"));
        }
        let value = args
            .next()
            .filter(|v| !v.starts_with("--"))
            .ok_or_else(|| format!("missing value for {key}"))?;
        if options.insert(key.clone(), value).is_some() {
            return Err(format!("duplicate option {key}"));
        }
    }
    let root = PathBuf::from(options.get("--root").map(String::as_str).unwrap_or("."));
    if command == "input" {
        let get = |key: &str| options.get(key).ok_or_else(|| format!("missing {key}"));
        let start = get("--line-start")?
            .parse()
            .map_err(|_| "invalid --line-start")?;
        let end = get("--line-end")?
            .parse()
            .map_err(|_| "invalid --line-end")?;
        let input = snapshot(&root, get("--path")?, start, end)?;
        println!(
            "{}",
            serde_json::to_string_pretty(&input).map_err(|e| e.to_string())?
        );
        return Ok(());
    }
    let mut requirements = discover(&root)?;
    if let Some(id) = options.get("--requirement") {
        requirements.retain(|r| &r.id == id);
        if requirements.is_empty() {
            return Err(format!("unknown requirement {id}"));
        }
    }
    if command == "requirements" {
        println!(
            "{}",
            serde_json::to_string_pretty(&requirements).map_err(|e| e.to_string())?
        );
        return Ok(());
    }
    let errors: Vec<_> = requirements
        .iter()
        .flat_map(|r| validate(&root, r))
        .collect();
    if !errors.is_empty() {
        return Err(format!(
            "{}\nEvidence check failed: {} issue(s) across {} requirement(s).",
            errors.join("\n"),
            errors.len(),
            requirements.len()
        ));
    }
    if !options.contains_key("--requirement") {
        build_skill(&root)?;
    }
    println!(
        "Evidence is current for {} requirement(s). Justifications were not evaluated.",
        requirements.len()
    );
    Ok(())
}

fn targeted_check_ignores_other_missing_evidence() {
    let f = Fixture::new();
    f.save(&f.evidence());
    f.write(
        "chapters/nested/contract.md",
        "{req}`test.rule` Preserve **all** data.\n\n{req}`other.rule` Unattested.",
    );
    assert!(
        f.cli(&["check", "--requirement", "test.rule"])
            .status
            .success()
    );
    assert!(!f.cli(&["check"]).status.success());
}

fn cli_filter_does_not_hide_unknown_requirement() {
    let f = Fixture::new();
    f.save(&f.evidence());
    assert!(
        f.cli(&["check", "--requirement", "test.rule"])
            .status
            .success()
    );
    for args in [
        vec!["check", "--requirement", "unknown.rule"],
        vec!["check", "--unknown", "x"],
        vec!["check", "--requirement"],
        vec!["input"],
        vec!["bogus"],
    ] {
        assert!(!f.cli(&args).status.success(), "{args:?}");
    }
}

use std::{fs, path::PathBuf, process::Command};

struct Fixture(PathBuf);
impl Fixture {
    fn new() -> Self {
        let root = std::env::temp_dir().join(format!("language-lab-build-{}", std::process::id()));
        fs::create_dir_all(root.join("chapters")).unwrap();
        fs::create_dir_all(root.join("evidence")).unwrap();
        fs::create_dir_all(root.join("src")).unwrap();
        fs::write(root.join("book.toml"), "[book]\nsrc='chapters'\n").unwrap();
        fs::write(
            root.join("chapters/SUMMARY.md"),
            "- [Contract](contract.md)\n",
        )
        .unwrap();
        fs::write(
            root.join("chapters/contract.md"),
            "{req}`test.build` Build it.\n",
        )
        .unwrap();
        fs::write(root.join("evidence/test.build.json"), serde_json::json!({
            "requirement":"Build it.", "inputs":[{"path":"book.toml","line_start":1,"line_end":1,"contents":"[book]\n"}],"justification":"fixture"
        }).to_string()).unwrap();
        let f = Self(root);
        f.write(
            "Cargo.toml",
            "[package]\nname='build-fixture'\nversion='0.1.0'\nedition='2021'\n[workspace]\n",
        );
        f.write(
            "Cargo.lock",
            "version = 4\n[[package]]\nname = 'build-fixture'\nversion = '0.1.0'\n",
        );
        f.write("src/main.rs", "fn main() {}\n");
        f
    }
    fn write(&self, path: &str, contents: &str) {
        fs::write(self.0.join(path), contents).unwrap();
    }
    fn command(&self) -> Command {
        let mut cmd = Command::new(env!("CARGO_BIN_EXE_language-lab-ci"));
        // The caller's working directory differs from the selected repository.
        cmd.current_dir(self.0.parent().unwrap())
            .args(["check", "--root"])
            .arg(self.0.file_name().unwrap());
        cmd.env("CARGO_NET_OFFLINE", "true");
        cmd
    }
}
impl Drop for Fixture {
    fn drop(&mut self) {
        fs::remove_dir_all(&self.0).unwrap();
    }
}

#[test]
fn full_check_builds_locked_project_and_propagates_failures() {
    let f = Fixture::new();
    let out = f.command().output().unwrap();
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    // Compiler errors prove the command actually compiles the selected project.
    f.write(
        "src/main.rs",
        "compile_error!(\"intentional build failure\"); fn main() {}\n",
    );
    let out = f.command().output().unwrap();
    assert!(!out.status.success());
    let error = String::from_utf8_lossy(&out.stderr);
    assert!(error.contains("intentional build failure"));
    assert!(error.contains("Skill build failed"));
    assert!(!String::from_utf8_lossy(&out.stdout).contains("Evidence is current"));
    assert!(
        f.command()
            .args(["--requirement", "test.build"])
            .output()
            .unwrap()
            .status
            .success()
    );
    f.write("src/main.rs", "fn main() {}\n");
    let lock = f.0.join("Cargo.lock");
    let original = fs::read(&lock).unwrap();
    f.write(
        "Cargo.lock",
        "version = 4\n[[package]]\nname = 'build-fixture'\nversion = '9.0.0'\n",
    );
    let before = fs::read(&lock).unwrap();
    let out = f.command().output().unwrap();
    assert!(!out.status.success());
    assert!(String::from_utf8_lossy(&out.stderr).contains("--locked"));
    assert_eq!(fs::read(&lock).unwrap(), before);
    fs::remove_file(&lock).unwrap();
    let out = f.command().output().unwrap();
    assert!(!out.status.success());
    assert!(String::from_utf8_lossy(&out.stderr).contains("missing"));
    assert!(!lock.exists());
    fs::write(&lock, original).unwrap();
    let empty_path = f.0.join("empty-path");
    fs::create_dir(&empty_path).unwrap();
    let out = f.command().env("PATH", empty_path).output().unwrap();
    assert!(!out.status.success());
    assert!(String::from_utf8_lossy(&out.stderr).contains("could not run cargo"));
    fs::remove_file(f.0.join("Cargo.toml")).unwrap();
    let out = f.command().output().unwrap();
    assert!(!out.status.success());
    assert!(String::from_utf8_lossy(&out.stderr).contains("Cargo.toml"));
}
